"""Fixed supplied CCA/constant/frequency-permuted reference; exact donor bodies."""
import sys,types
SOURCES={'protocol.py': '"""Fixed prospective OpenBMI overt-gaze SSVEP contract; no data-dependent defaults."""\nSCHEMA = "neural084_scores_v1"\nPEOPLE = tuple(range(1, 55))\nSESSIONS = (1, 2)\nPHASES = ("train", "test")\nCLASSES = (1, 2, 3, 4)\nDIRECTIONS = ("up", "left", "right", "down")\nFREQUENCIES = tuple(60.0 / n for n in (5, 7, 9, 11))\nCHANNELS = ("P7", "P3", "Pz", "P4", "P8", "PO9", "PO10", "O1", "Oz", "O2")\nFS_SOURCE = 1000\nFS_OUTPUT = 100\nSAMPLES_SOURCE = 4000\nSAMPLES_OUTPUT = 400\nTRIALS_PHASE = 100\nTRIALS_PERSON = 400\nTRIALS_CLASS_PHASE = 25\nMAX_SUBMISSION_BYTES = 262144\n\n\ndef fold_name(person):\n    if type(person) is not int or person not in PEOPLE:\n        raise ValueError("full designated person roster1..54")\n    return "fold%03d" % person\n', 'io_utils.py': '"""Portable bounded file transport. No candidate execution or global state."""\nimport hashlib\nimport json\nimport math\nimport os\nfrom pathlib import Path\nimport re\nimport stat\n\n\ndef need(ok, message):\n    if not ok:\n        raise ValueError(message)\n\n\ndef exact(value, fields):\n    need(type(value) is dict and set(value) == set(fields), \'Exact object fields\')\n\n\ndef canonical(value):\n    return (json.dumps(value, sort_keys=True, separators=(\',\', \':\'), ensure_ascii=True,\n                       allow_nan=False) + \'\\n\').encode(\'ascii\')\n\n\ndef pin(body):\n    return {\'bytes\': len(body), \'sha256\': hashlib.sha256(body).hexdigest()}\n\n\ndef check_pin(value, cap, empty=False):\n    exact(value, [\'bytes\', \'sha256\'])\n    need(type(value[\'bytes\']) is int and int(not empty) <= value[\'bytes\'] <= cap and\n         type(value[\'sha256\']) is str and re.fullmatch(\'[a-f0-9]{64}\', value[\'sha256\']), \'Exact bounded pin\')\n\n\ndef resolve(root, relative):\n    need(type(relative) is str and relative and not Path(relative).is_absolute() and\n         all(x not in (\'\', \'.\', \'..\') for x in relative.split(\'/\')) and \'\\\\\' not in relative,\n         \'Safe relative input path\')\n    return Path(root) / relative\n\n\ndef regular(path):\n    path = Path(path).absolute()\n    need(all(not p.is_symlink() for p in (path, *path.parents)), \'No linked paths\')\n    return path\n\n\ndef read(path, cap, expected=None, empty=False, retain=True):\n    path = regular(path)\n    if expected is not None:\n        check_pin(expected, cap, empty)\n    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)\n    with os.fdopen(fd, \'rb\') as stream:\n        before = os.fstat(stream.fileno())\n        need(stat.S_ISREG(before.st_mode) and before.st_nlink == 1 and\n             int(not empty) <= before.st_size <= cap, \'Bounded ordinary single-link input\')\n        if expected is not None:\n            need(before.st_size == expected[\'bytes\'], \'Exact byte size\')\n        digest = hashlib.sha256(); count = 0; chunks = []\n        for block in iter(lambda: stream.read(1048576), b\'\'):\n            count += len(block); need(count <= cap, \'Bounded stream\')\n            digest.update(block)\n            if retain:\n                chunks.append(block)\n        after = os.fstat(stream.fileno())\n        need(count == before.st_size and all(getattr(before, key) == getattr(after, key)\n             for key in (\'st_dev\', \'st_ino\', \'st_size\', \'st_nlink\', \'st_mtime_ns\', \'st_ctime_ns\')), \'Stable full file\')\n    observed = {\'bytes\': count, \'sha256\': digest.hexdigest()}\n    need(expected is None or observed == expected, \'Exact content binding\')\n    return b\'\'.join(chunks) if retain else observed\n\n\ndef decode(body):\n    def pairs(rows):\n        result = {}\n        for key, value in rows:\n            need(key not in result, \'Duplicate JSON field\'); result[key] = value\n        return result\n    def finite(value):\n        number = float(value); need(math.isfinite(number), \'Finite JSON number\'); return number\n    def integer(value):\n        need(len(value) <= 18, \'Bounded integer\'); return int(value)\n    def invalid(value):\n        raise ValueError(\'Nonstandard JSON constant\')\n    try:\n        return json.loads(body.decode(\'utf-8\'), object_pairs_hook=pairs, parse_float=finite,\n                          parse_int=integer, parse_constant=invalid)\n    except (UnicodeError, RecursionError, OverflowError) as error:\n        raise ValueError(\'Malformed bounded JSON\') from error\n\n\ndef json_file(path, cap=524288, expected=None):\n    return decode(read(path, cap, expected))\n\n\ndef put(path, value, cap=524288):\n    path = regular(path); body = canonical(value); need(len(body) <= cap, \'Output cap\')\n    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)\n    with os.fdopen(fd, \'wb\') as stream:\n        stream.write(body); stream.flush(); os.fsync(stream.fileno())\n    path.chmod(0o444)\n    return pin(body)\n\n\ndef fresh(path):\n    path = regular(path)\n    need(not path.exists() and path.parent.is_dir(), \'Fresh owned output directory\')\n    path.mkdir(mode=0o700)\n    return path\n\n\ndef asset(root, record, decode_json=False):\n    expected = {k: record[k] for k in (\'bytes\', \'sha256\')}\n    path = resolve(root, record[\'path\'])\n    if decode_json:\n        return json_file(path, record[\'bytes\'], expected)\n    return read(path, record[\'bytes\'], expected, retain=False)\n\n\ndef program_pin(value):\n    check_pin(value, 131072)\n', 'reference_cca.py': '"""Unfitted phase-invariant two-harmonic CCA reference for the new representation.\n\nThis is independent Python source, not numerically qualified MATLAB parity.\n"""\nimport argparse\nimport io\nfrom pathlib import Path\nimport numpy as np\nfrom protocol import *\nfrom io_utils import need, read, json_file, resolve, put\n\n\ndef orthonormal_span(a):\n    a=np.asarray(a,dtype=np.float64)\n    need(a.ndim==2 and np.isfinite(a).all(),"finite matrix")\n    # Normalize before centering/SVD; finite extreme input cannot overflow sums.\n    scale=float(np.max(np.abs(a)))\n    if scale==0:return np.zeros((a.shape[0],0))\n    a=a/scale;a=a-a.mean(axis=0,keepdims=True)\n    u,s,_=np.linalg.svd(a,full_matrices=False)\n    if not len(s) or s[0]==0:return u[:,:0]\n    threshold=max(a.shape)*np.finfo(np.float64).eps*s[0]\n    return u[:,s>threshold]\n\n\ndef scores(epoch):\n    need(epoch.shape==(10,400) and np.isfinite(epoch).all(),"finite10x400 query")\n    x=orthonormal_span(epoch.T)\n    time=np.arange(400)/100.0+0.0045\n    result=[]\n    for f in FREQUENCIES:\n        columns=[g(2*np.pi*h*f*time) for h in (1,2) for g in (np.sin,np.cos)]\n        y=orthonormal_span(np.asarray(columns).T)\n        if x.shape[1]==0 or y.shape[1]==0:r=0.0\n        else:r=float(np.linalg.svd(x.T@y,compute_uv=False)[0])\n        need(np.isfinite(r) and -1e-12<=r<=1+1e-12,"defined canonical correlation")\n        result.append(min(1.0,max(0.0,r)))\n    return result\n\n\ndef main():\n    p=argparse.ArgumentParser(description=__doc__);p.add_argument("--input",type=Path,required=True);p.add_argument("--out",type=Path,required=True)\n    p.add_argument("--mode",choices=("cca","constant","frequency-permuted"),default="cca");a=p.parse_args()\n    meta=json_file(a.input/"fold.json",262144)\n    need(meta["schema"]=="neural084_fold_v1" and len(meta["ids"])==400,"full fold")\n    d=meta["queries"];x=np.load(io.BytesIO(read(resolve(a.input,d["path"]),7000000,{k:d[k] for k in ("bytes","sha256")})),allow_pickle=False)\n    need(x.dtype==np.dtype("float32") and x.shape==(400,10,400),"public query schema")\n    predictions=[]\n    for qid,epoch in zip(meta["ids"],x):\n        values=[0.0]*4 if a.mode=="constant" else scores(epoch)\n        if a.mode=="frequency-permuted":values=values[1:]+values[:1]\n        predictions.append({"id":qid,"scores":values})\n    put(a.out,{"schema":SCHEMA,"generation":meta["generation"],"fold":meta["fold"],\n               "predictions":predictions},MAX_SUBMISSION_BYTES)\n\n\nif __name__=="__main__":main()\n'}
for filename in ("protocol.py","io_utils.py","reference_cca.py"):
    name=filename[:-3]
    module=types.ModuleType(name);module.__file__=filename;sys.modules[name]=module
    exec(compile(SOURCES[filename],filename,"exec"),module.__dict__)
if __name__=="__main__":sys.modules["reference_cca"].main()
